#include<iostream>
#include<cstdio>

using namespace std;

class Answer {
public:
    Answer() { day = 10; year = 365; }

    int N; // Input variable
    int day;
    int year;

    unsigned long long count(int cnt); // Function declaration
    void set(); // Input function
    void OutPut(); // Output function

    bool empty(); // Check if N is empty
    bool ans(); // Process answer
};

unsigned long long Answer::count(int cnt) {
    if (cnt < 0) return 0;
    if (cnt == 0) return 1;

    unsigned long long dp[4] = {0}; // Use a rolling array of size 4
    dp[0] = 1; // Base case
    dp[1] = 1; // Base case
    dp[2] = 2; // Base case

    for (int i = 3; i <= cnt; ++i) {
        dp[i % 4] = dp[(i - 1) % 4] + dp[(i - 2) % 4] + dp[(i - 3) % 4]; // Rolling update
    }
    return dp[cnt % 4]; // Return final result
}

void Answer::OutPut() {
    if (N == 0) return;
    unsigned long long ans_ = 1; // Change to unsigned long long
    ans_ += count(N) / (day * year); // Compute answer

    printf("%llu\n", ans_); // Consolidated output
}

void Answer::set() {
    scanf("%d", &N); // Use scanf for input
    if (N < 0 || N > 999) {
        printf("Invalid input. Please enter a value between 0 and 999.\n");
        N = 0; // Reset N for invalid input
    }
}

bool Answer::empty() {
    return N != 0;
}

bool Answer::ans() {
    set();
    OutPut();
    return empty();
}

int main() {
    Answer ans;
    while (ans.ans());
    return 0;
}

